"""Build the Watch program's factual support and privacy pages; no trackers."""
from pathlib import Path
from html import escape
import shutil

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://isaiahdupree.github.io/sonance-apps/'
APPS = {
 'workshop-wrist': ('Workshop Wrist', 'Your checklist, close at hand.', ['Create an ordered checklist and work notes on iPhone.', 'Check off steps on your paired Watch. Corrections remain in revision history.', 'Use Sync with companion to retry delivery. Export records before removing a project.'], 'Your instructions guide the work. Workshop Wrist does not control equipment or certify a procedure.'),
 'referee-assistant': ('Match assistant', 'Keep the match record on your wrist.', ['Enter the team names and period lengths in seconds.', 'Start or pause the clock, record scores and add event notes.', 'Correct a score or undo a note in the event history. Export the match record when finished.'], 'You choose the match rules and period lengths. Optional notifications depend on system permission and delivery; keep an appropriate backup timekeeping method.'),
 'baby-care-handoffs': ('Care handoffs', 'A clear record of the care you entered.', ['Add a child, then record feeding, diaper or sleep events.', 'Review recorded times and notes. End an open sleep entry or correct an event in history.', 'Export the selected child’s records or erase that child and request paired erasure.'], 'Care handoffs is a caregiver-entered journal. It does not monitor a child, offer medical advice or provide household cloud sharing.'),
 'anki-continuity': ('Portable Cards', 'Your own cards, ready for a short review.', ['Author a deck on iPhone, or import a version 1 portable JSON deck.', 'Reveal a card, then choose Again or Good in independent deck mode.', 'Export the portable deck and saved review records when needed.'], 'Independent mode uses its own documented schedule. An Anki Desktop file bridge is in development; Anki synchronization and affiliation are not claimed for this preview.'),
 'agent-pulse': ('Agent Pulse', 'Selected job updates, with their dates.', ['Sign in to an account with an explicitly configured workspace.', 'Select the workspace on iPhone and pair it with Watch.', 'Refresh to read dated job states. An alert acknowledgement records a Pulse receipt; it does not start, stop or change an Orion job.'], 'A configured workspace and source publisher are required. Old cached values stay dated. The deployed backend has been tested with isolated accounts; owner-feed and paired workflow acceptance remain in progress.'),
 'creator-pulse': ('Creator Pulse', 'Publication receipts and measured updates.', ['Sign in to an account with an explicitly configured workspace.', 'Select the account-scoped workspace on iPhone and pair it with Watch.', 'Refresh to read publication states and available measured values. Unknown collection times or values remain unknown.'], 'A configured workspace and source publisher are required. Creator Pulse has no social publishing or scheduling controls, revenue estimates or invented metrics. Owner-feed and paired workflow acceptance remain in progress.')
}
STYLE = "body{font:17px/1.65 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;max-width:820px;margin:56px auto;padding:0 24px;color:#17283a;background:#fafaf7}a{color:#075f70}h1{font-size:2.6rem;line-height:1.1}h2{margin-top:1.8em}.status{background:#e8eef4;border-radius:14px;padding:16px}.icon{width:96px;height:96px;border-radius:22px}header{border-bottom:1px solid #d8dfe5;padding-bottom:20px}footer{margin-top:44px;padding-top:20px;border-top:1px solid #d8dfe5}li{margin:10px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}.card{padding:20px;border:1px solid #d8dfe5;border-radius:18px}"

def page(title, description, path, content):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{BASE+path}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><style>{STYLE}</style></head><body>{content}<footer>Isaiah Dupree · Updated October 24, 2026 · <a href="mailto:isaiahdupree33@gmail.com">Contact support</a></footer></body></html>\n'''

def local_policy(name):
    return f'''<h2>Data and storage</h2><p>{escape(name)} stores the records you enter on your device and transfers them to its paired companion when you request synchronization. It does not upload those records to a developer-operated server and contains no advertising or analytics SDK. Device backups may be managed separately through Apple and your device settings.</p><h2>Exports and support</h2><p>Exports contain the selected records and history. You choose where to share them; recipients keep their own copies. If you email support, the email provider processes the information you send. Please omit private records, passwords and verification codes. Request removal of a support message by contacting the same address.</p><h2>Erasure and paired copies</h2><p>Erasing a scope removes its local content and history while retaining a marker that prevents old transfers from restoring erased content. A disconnected companion applies erasure after it receives that marker. Existing exports and device backups remain separately managed. Delete or erase the other device’s copy too when you cannot reconnect it.</p>'''

def pulse_policy(name):
    return f'''<h2>Account and workspace data</h2><p>{escape(name)} uses Supabase for account authentication and its workspace service. Your sign-in email and authentication information are processed by that service. The workspace stores your account identifier, selected source identifiers, sanitized dated snapshots and applicable alert acknowledgement receipts. Source logs, commands, passwords, social access tokens and job-control credentials are not included in snapshots.</p><h2>Device storage and pairing</h2><p>The iPhone keeps its sign-in session in device-only Keychain storage. Watch receives a separate scoped credential with a maximum one-hour lifetime, rather than the phone’s sign-in session. Selected snapshots and pending receipts are cached in the app’s protected storage. No analytics, advertising or tracking SDK is included.</p><h2>Sign-out and erasure</h2><p>Use Sign out and revoke paired access on iPhone to remove local protected content, request paired erasure and revoke the selected phone/Watch credentials. If offline, sign-out remains unfinished until you reconnect and retry; a disconnected Watch may retain its credential until erasure arrives or the credential expires. Erase this Watch removes its local content; revoke server access from iPhone too.</p><h2>Server retention and deletion</h2><p>Workspace records remain until the workspace administrator removes the scope and its associated records. Source records in Orion or Airtime remain independently managed. To request workspace or account deletion, contact support from the account email. We verify the request before removing account-linked data and never ask you to send a password or verification code. This development preview does not offer public account registration. Retention automation is part of release preparation.</p><h2>Support email</h2><p>The email provider processes information you choose to send to support. Please omit source logs and private content. Request removal of a support message at the contact address below.</p>'''

def build(icon_root):
    for slug, (name, subtitle, steps, limit) in APPS.items():
        directory = ROOT/slug; directory.mkdir(exist_ok=True)
        assets=directory/'assets';assets.mkdir(exist_ok=True)
        icon=icon_root/slug/'Resources/Assets.xcassets/AppIcon.appiconset/Icon.png'
        shutil.copyfile(icon,assets/'icon.png')
        body=f'<header><p><a href="../watch-program/">Watch projects</a></p><img class="icon" src="assets/icon.png" alt=""><h1>{escape(name)}</h1><p>{escape(subtitle)}</p></header><p class="status">Development preview. Simulator acceptance and store preparation are in progress. This Watch release is not currently offered for download here.</p><h2>Getting started</h2><ol>'+''.join('<li>'+escape(s)+'</li>' for s in steps)+f'</ol><h2>What to expect</h2><p>{escape(limit)}</p><h2>Pairing and offline use</h2><p>Open the app on both paired devices when checking a transfer. Waiting to send is different from a confirmed result. A disconnected device may continue to show older saved records.</p><p><a href="privacy/">Privacy policy</a></p><h2>Contact support</h2><p>Email <a href="mailto:isaiahdupree33@gmail.com?subject={slug}%20support">isaiahdupree33@gmail.com</a> with the app version, device model, operating-system version and the steps leading to the problem. Do not send private records, passwords or verification codes.</p>'
        (directory/'index.html').write_text(page(name+' support',subtitle,slug+'/',body))
        privacy=directory/'privacy';privacy.mkdir(exist_ok=True)
        content=f'<header><p><a href="../">{escape(name)} support</a></p><h1>Privacy policy</h1><p>{escape(name)} · development preview</p></header>'+(pulse_policy(name) if slug.endswith('-pulse') else local_policy(name))
        (privacy/'index.html').write_text(page(name+' privacy policy','How '+name+' handles records and deletion.',slug+'/privacy/',content))
    directory=ROOT/'watch-program';directory.mkdir(exist_ok=True)
    cards=''.join(f'<article class="card"><img class="icon" src="../{slug}/assets/icon.png" alt=""><h2>{escape(name)}</h2><p>{escape(subtitle)}</p><a href="../{slug}/">Progress and support</a></article>' for slug,(name,subtitle,_,_) in APPS.items())
    body='<header><p><a href="../">Isaiah’s apps</a></p><h1>Small jobs. On your wrist.</h1><p>Apple Watch projects for everyday records, checklists and focused updates.</p></header><p class="status">Eleven researched Watch projects are being developed and prepared for review. The pages below describe current work; App Store availability has not been announced.</p><div class="cards">'+cards+'</div><h2>More in the program</h2><ul><li><a href="../arenacue/">ArenaCue — riding routines and ride notes</a></li><li><a href="../knitcheckpoint/">KnitCheckpoint — knitting progress and pattern checkpoints</a></li><li>Kawaii Coffee Watch — companion recipe and brew workflow in development</li><li>Riff Capture — companion original-audio capture in development</li><li>EverReach Watch — selected-contact companion workflow in development</li></ul><h2>Follow development</h2><p>For a project question or testing inquiry, <a href="mailto:isaiahdupree33@gmail.com?subject=Watch%20program">email Isaiah</a>. We will confirm availability when a release is ready.</p>'
    (directory/'index.html').write_text(page('Isaiah’s Apple Watch projects','Eleven Apple Watch projects, current development progress, support and privacy.', 'watch-program/',body))

if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--icon-root',type=Path,required=True)
    build(parser.parse_args().icon_root)
